// C++14 generic lambda that can take any pointer-like type.
// 'const auto&' uses template deduction rules to accept arguments by const reference.
auto derefLess = [](const auto& p1, const auto& p2) {
    return *p1 < *p2; 
};

#include <memory>
auto p1 = std::make_unique<int>(10);
auto p2 = std::make_shared<int>(20);
int x = 30;
int* p3 = &x;

// The same lambda works with different types.
bool r1 = derefLess(p1, p2); // Works with unique_ptr and shared_ptr
bool r2 = derefLess(p3, p1); // Works with raw pointer and unique_ptr
